# xfer.sh — thin wrapper around the transfer vendor CLI.

_xferq() { "$XFERQ" "$@"; }

# xfer_send PARTNER FILE NAME — uploads FILE as NAME and prints the ticket.
# Transient spool errors are retried; a malformed answer counts as a failure.
xfer_send() {
  local partner=$1 file=$2 name=$3 out rc try=0
  while :; do
    out=$(_xferq send --to "$partner" --file "$file" --as "$name" 2>&1); rc=$?
    if [ "$rc" -eq 0 ]; then
      case "$out" in
        T[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) printf '%s' "$out"; return 0 ;;
        *) warn "unexpected answer from transfer CLI: $out"; return 1 ;;
      esac
    fi
    try=$((try + 1))
    if [ "$try" -gt "$SEND_RETRIES" ]; then
      warn "send $name to $partner failed ($out, exit $rc)"
      return 1
    fi
    log "retrying $name ($out)"
  done
}

# xfer_ls PARTNER — name<TAB>bytes<TAB>ticket for files in the partner's box.
xfer_ls() { _xferq ls --to "$1"; }

# xfer_pull PARTNER NAME — file contents on stdout.
xfer_pull() { _xferq pull --to "$1" --name "$2"; }
# Test helpers. Each test file sources this, calls t_setup, then asserts.
T_HOME=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
T_FAIL=0
T_PASS=0

t_setup() {
  T_WORK=$(mktemp -d)
  trap 't_cleanup' EXIT
  export PAYOUT_WORK_DIR="$T_WORK/work"
  export PAYOUT_OUT_DIR="$T_WORK/out"
  export PAYOUT_TXN_FILE="$T_HOME/fixtures/txns-202610.tsv"
  export PAYOUT_PARTNERS_FILE="$T_HOME/conf/partners.conf"
  export XFERQ_HOME="$T_WORK/spool"
  mkdir -p "$XFERQ_HOME"
}

t_cleanup() { [ -n "${T_WORK:-}" ] && rm -rf "$T_WORK"; }

# Loads the libraries into the test shell (for unit tests).
t_source_libs() {
  export LC_ALL=C.UTF-8
  export PAYOUT_HOME="$T_HOME"
  . "$T_HOME/steps/_env.sh"
}

payout() { "$T_HOME/bin/payout" "$@"; }

ok()   { T_PASS=$((T_PASS + 1)); printf 'ok   - %s\n' "$1"; }
fail() { T_FAIL=$((T_FAIL + 1)); printf 'FAIL - %s\n' "$1"; [ -n "${2:-}" ] && printf '       %s\n' "$2"; return 0; }

assert_eq() {
  if [ "$2" = "$3" ]; then ok "$1"; else fail "$1" "expected [$3] got [$2]"; fi
}

assert_contains() {
  if printf '%s' "$2" | grep -qF -- "$3"; then ok "$1"; else fail "$1" "missing [$3]"; fi
}

assert_rc() {
  if [ "$2" -eq "$3" ]; then ok "$1"; else fail "$1" "expected exit $3 got $2"; fi
# csvfile.sh — settlement file body (PAY-IF-03 rev.2).
#
#   H,<sender>,<partner>,<date>,<part>/<parts>
#   D,<txn>,<date>,<amount>,<fee>,<net>      one per transaction
#   T,<detail count>,<net total>
#
# Lines end in CRLF when LINE_END=crlf.

_eol() { [ "${LINE_END:-lf}" = crlf ] && printf '\r\n' || printf '\n'; }

# csv_render DATE PARTNER PART PARTS < rows(txn<TAB>amount<TAB>fee)
csv_render() {
  local date=$1 partner=$2 part=$3 parts=$4 txn amount fee net n=0 total=0
  printf 'H,%s,%s,%s,%d/%d' "$SENDER_ID" "$partner" "$date" "$part" "$parts"; _eol
  while IFS=$'\t' read -r txn amount fee; do
    [ -n "$txn" ] || continue
    net=$(money_net "$amount" "$fee")
    printf 'D,%s,%s,%s,%s,%s' "$txn" "$date" "$amount" "$fee" "$net"; _eol
    n=$((n + 1)); total=$((total + net))
  done
  printf 'T,%d,%d' "$n" "$total"; _eol
}

